// fuse_app Wayland backend (Linux): libwayland-client, libxkbcommon and libwayland-cursor are loaded at runtime
// (dlopen), like the X11 path, so neither the Wayland headers nor the libraries are needed to build. xdg-shell (and
// the optional xdg-decoration) protocol tables are written out here instead of being generated by wayland-scanner.
//
// What it does: xdg_toplevel windows, wl_shm software present (the CPU raster), the wl_surface handed to the Vulkan
// presenter (VK_KHR_wayland_surface), wl_pointer / wl_keyboard input (xkbcommon keymaps, client-side key repeat),
// integer output scale (wl_output.scale -> wl_surface.set_buffer_scale), xdg-decoration server-side frames when the
// compositor offers them, libwayland-cursor theme cursors, custom-chrome move / resize / maximise / minimise through
// xdg_toplevel. Not here (yet): popups / tool windows as xdg_popup / subsurfaces (they stay in-window overlays),
// fractional scale, text-input-v3 (IME pre-edit), the Wayland clipboard (wl_data_device), window icons.
//
// Selection (NativePlatform): Wayland when $FUSE_APP_BACKEND=wayland, or when $DISPLAY is unset and a compositor
// answers on $WAYLAND_DISPLAY; X11 otherwise ($FUSE_APP_BACKEND=x11 forces X11).
#pragma once

#if !defined(_WIN32) && !defined(__ANDROID__)
#include "fuse/app/app.hpp"
#include "fuse/app/platform.hpp"

#include <string>
#include <vector>

namespace fuse::app::wl {

struct Backend;
struct Window;

/// Keysym (X11 / xkb share the values) -> FUSE key; `ascii` set for printable ASCII keys.
using KeysymMap = fuse::ui::Key (*)(unsigned long sym, bool& ascii);

/// True when the environment asks for Wayland ($FUSE_APP_BACKEND=wayland, or no $DISPLAY with $WAYLAND_DISPLAY set).
bool wanted();
/// dlopens libwayland-client and connects ($WAYLAND_DISPLAY); null (and `err`) without a compositor or without
/// wl_compositor / wl_shm / xdg_wm_base. `dpiAware` false: every window keeps scale 1.
Backend* open(std::string& err, bool dpiAware, KeysymMap keys);
void close(Backend* b);
/// The open backend (one per process), null when the NativePlatform runs on X11 / headless.
Backend* current();

int fd(const Backend* b);
void* display(const Backend* b); ///< wl_display*
/// Event pump halves: before poll() (prepare_read + flush; returns the connection fd), after it (read or cancel,
/// dispatch). Key repeat runs in after().
int beforePoll(Backend* b);
void afterPoll(Backend* b, bool readable);
/// Seconds until the next key repeat (inf when none is due).
fuse::ui::f32 nextTimeout(const Backend* b);
/// Blocks until the compositor answered everything sent so far.
bool roundtrip(Backend* b);

/// An xdg_toplevel for `w`: title, scale of the output(s) known, waits for the first configure. `focused` is kept
/// current with the keyboard focus.
Window* createWindow(Backend* b, AppWindow& w, bool* focused, std::string& err);
void destroyWindow(Backend* b, Window* win);
void* surface(const Window* win); ///< wl_surface*
/// The software presenter: the window's whole CPU raster into a wl_shm buffer, attached, damaged, committed.
void presentShm(Backend* b, Window* win, const fuse::ui::Image& img);
/// Before a Vulkan present: sends a changed buffer scale (it applies with the swapchain's commit).
void beforeVulkanPresent(Backend* b, Window* win);
/// The last frame committed through presentShm (what the compositor shows for a software window).
bool capture(const Window* win, fuse::ui::Image& out);
void setCursor(Backend* b, Window* win, fuse::ui::CursorShape c);
/// Window scale (rounded to an integer buffer scale) like an output change does; keeps the logical size.
void setScale(Backend* b, Window* win, fuse::ui::f32 scale);
/// The client picks a toplevel's size on Wayland: resizes the window (logical units) and redraws.
void resize(Backend* b, Window* win, unsigned width, unsigned height);
std::vector<DisplayInfo> displays(const Backend* b);
int bufferScale(const Window* win);
unsigned long long serialOf(const Window* win); ///< configures acknowledged (tests)

/// Input injection for tests (Wayland has no way to post events to another client's surface): delivered as if the
/// compositor had sent them. `at` in device pixels; kind 0 move, 1 left down, 2 left up.
void injectPointer(Backend* b, Window* win, fuse::ui::Vec2 at, int kind);
/// Delivers a key press + release by Linux evdev code (KEY_A = 30 ...) through the keymap path.
void injectKey(Backend* b, Window* win, unsigned evdevCode);
void injectClose(Window* win); ///< xdg_toplevel.close

/// No-compositor checks for the fuse_app_wayland gate: libraries resolve, protocol tables are consistent,
/// xkbcommon turns evdev codes into the expected keysyms / text. Empty string = pass, else what failed.
std::string selfTest(KeysymMap keys);

} // namespace fuse::app::wl
#endif
